<template><el-card shadow="never"><template #header><div class="head"><div><b>项目成员</b><p>项目权限与全局角色共同决定可执行的操作。</p></div><el-button type="primary" @click="visible=true">添加成员</el-button></div></template><el-table v-loading="loading" :data="items"><el-table-column prop="username" label="用户"/><el-table-column prop="email" label="邮箱"/><el-table-column label="项目权限" width="180"><template #default="{row}"><el-select v-model="row.access" @change="change(row)"><el-option label="只读" value="read"/><el-option label="可编辑" value="write"/></el-select></template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="danger" @click="remove(row)">移除</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!items.length" description="暂无显式项目成员"/></el-card><el-dialog v-model="visible" title="添加项目成员" width="460px"><el-form label-position="top"><el-form-item label="用户名"><el-input v-model="form.username"/></el-form-item><el-form-item label="项目权限"><el-radio-group v-model="form.access"><el-radio-button value="read">只读</el-radio-button><el-radio-button value="write">可编辑</el-radio-button></el-radio-group></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="add">添加</el-button></template></el-dialog></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{projectApi}from'@/api';const projectId=String(useRoute().params.id),loading=ref(false),items=ref<any[]>([]),visible=ref(false),form=reactive({username:'',access:'read' as 'read'|'write'});async function load(){loading.value=true;try{const r:any=await projectApi.members(projectId);items.value=r?.data?.items||r?.data?.list||r?.data||[]}finally{loading.value=false}}async function add(){await projectApi.setMember(projectId,form);ElMessage.success('成员已添加');visible.value=false;form.username='';load()}async function change(row:any){await projectApi.setMember(projectId,{username:row.username,access:row.access});ElMessage.success('权限已更新')}async function remove(row:any){await ElMessageBox.confirm(`移除成员“${row.username}”？`,'移除成员',{type:'warning'});await projectApi.removeMember(projectId,row.user_id||row.id);ElMessage.success('成员已移除');load()}onMounted(load)</script>
<style scoped>.head{display:flex;justify-content:space-between;align-items:flex-start}.head p{margin:5px 0 0;color:var(--app-text-secondary);font-size:13px}</style>
